  ///
  /// Unlike [clone], this normalizes non-finite coordinates and negative zero
  /// as [LatLng.fromSdk] does, while retaining the original value unchanged.
  LatLng cloneForSdk() => LatLng.fromSdk(latitude, longitude);

SdkLatLngBounds([
    SdkBoundsCorner southWest = const SdkBoundsCorner.undefined(),
    SdkBoundsCorner northEast = const SdkBoundsCorner.undefined(),
  ])  : _southWest = _cloneCorner(southWest),
        _northEast = _cloneCorner(northEast) {
    final sw = _southWest.coordinate;
    final ne = _northEast.coordinate;
    if (sw != null && ne != null) {
      final swapLng = sw.longitude > ne.longitude;
      final swapLat = sw.latitude > ne.latitude;
      _southWest = SdkBoundsCorner.value(LatLng(
        swapLat ? ne.latitude : sw.latitude,
        swapLng ? ne.longitude : sw.longitude,
      ));
      _northEast = SdkBoundsCorner.value(LatLng(
        swapLat ? sw.latitude : ne.latitude,
        swapLng ? sw.longitude : ne.longitude,
      ));
    }
  }

/// Creates a numeric state without the SDK constructor's cloning or sorting.
  ///
  /// This represents corner values subsequently assigned through SDK setters;
  /// use the default constructor for ordinary SDK construction behavior.
  SdkLatLngBounds.raw([
    SdkBoundsCorner southWest = const SdkBoundsCorner.undefined(),
    SdkBoundsCorner northEast = const SdkBoundsCorner.undefined(),
  ])  : _southWest = southWest,
        _northEast = northEast;

const SdkBoundsCorner.undefined()
      : kind = SdkBoundsCornerKind.undefined,
        coordinate = null;

const SdkBoundsCorner.nullValue()
      : kind = SdkBoundsCornerKind.nullValue,
        coordinate = null;

/// The presence of an SDK bounds corner. JavaScript distinguishes a missing
/// argument (`undefined`) from an explicit `null`, although `isEmpty` treats
/// both as absent.
enum SdkBoundsCornerKind { undefined, nullValue, value }

static SdkBoundsCorner _cloneCorner(SdkBoundsCorner corner) =>
    switch (corner.kind) {
      SdkBoundsCornerKind.undefined => const SdkBoundsCorner.undefined(),
      SdkBoundsCornerKind.nullValue => const SdkBoundsCorner.nullValue(),
      SdkBoundsCornerKind.value =>
        SdkBoundsCorner.value(corner.coordinate!.cloneForSdk()),
    };
